    assert "operator_archive_package_delivery_report_acknowledgement_status_result_entry_id" in (
        reconciliation.required_operator_archive_package_delivery_report_acknowledgement_result_reconciliation_receipt_fields
    )
    assert reconciliation.required_operator_archive_package_delivery_report_acknowledgement_result_reconciliation_invariants[
        0
    ].startswith(
        "operator archive package delivery report acknowledgement result reconciliation planner must require final operator acknowledgement"
    )
    assert reconciliation.blocker_reason == (
        "operator_archive_package_delivery_report_acknowledgement_result_reconciliation_unimplemented"
    )
    assert (
        reconciliation.operator_archive_package_delivery_report_acknowledgement_result_reconciliation_allowed
        is False
    )
    assert (
        reconciliation.operator_archive_package_delivery_report_acknowledgement_result_entry_created
        is False
    )
    assert (
        reconciliation.operator_archive_package_delivery_report_final_operator_acknowledgement_entry_created
        is False
    )
    assert reconciliation.operator_notification_created is False
    assert reconciliation.private_read_url_created is False
    assert reconciliation.graph_mutated is False
    assert reconciliation.provider_calls_made is False
    assert reconciliation.retrieval_performed is False
    assert reconciliation.final_artifact_created is False


