def test_retention_billing_reconciliation_plan_records_disabled_requirements() -> None:
    chain = _accepted_midnight_oil_delivery_notification_reconciliation_plan_chain(
        goal="Plan retention and billing reconciliation after delivery notification reconciliation planning.",
        source_policy=["arxiv", "web"],
        requested_control_scope=[
            "budget_reservation_provider",
            "model_provider_route_executor",
            "retrieval_executor_source_receipts",
            "graph_mutation_writer",
            "final_html_artifact_writer",
            "operator_live_dispatch_enablement",
        ],
    )
    preflight = chain["preflight"]
    output_plan = chain["worker_output_aggregation_plan"]
    handoff_plan = chain["worker_synthesis_handoff_plan"]
    assembly_plan = chain["synthesis_bundle_assembly_plan"]
    draft_plan = chain["final_synthesis_draft_plan"]
    html_plan = chain["final_html_artifact_assembly_plan"]
    persistence_plan = chain["final_artifact_persistence_plan"]
    graph_commit_plan = chain["final_artifact_graph_commit_plan"]
    publish_plan = chain["final_artifact_publish_plan"]
    completion_plan = chain["final_artifact_completion_finalization_plan"]
    closure_plan = chain["final_run_closure_plan"]
    readiness_plan = chain["operator_notification_delivery_readiness_plan"]
    apply_plan = chain["operator_notification_delivery_apply_plan"]
    result_plan = chain["operator_notification_delivery_result_reconciliation_plan"]
    ledger_plan = chain["operator_delivery_ledger_reconciliation_plan"]
    card_plan = chain["workspace_delivery_card_reconciliation_plan"]
    notification_plan = chain["delivery_notification_reconciliation_plan"]

    retention_plan = retention_billing_reconciliation_plan_midnight_oil(
        MidnightOilRetentionBillingReconciliationPlanRequest(
            **_retention_billing_reconciliation_request_kwargs(
                chain,
                output_plan,
                handoff_plan,
                assembly_plan,
                draft_plan,
                html_plan,
                persistence_plan,
                graph_commit_plan,
                publish_plan,
                completion_plan,
                closure_plan,
                readiness_plan,
                apply_plan,
                result_plan,
                ledger_plan,
                card_plan,
                notification_plan,
            )
        )
    )

    assert retention_plan.receipt_id == (
        f"{preflight.run_id}-retention-billing-reconciliation-plan"
    )
    assert (
        retention_plan.delivery_notification_reconciliation_plan_receipt_id
        == notification_plan.receipt_id
    )
    assert (
        retention_plan.workspace_delivery_card_reconciliation_plan_receipt_id
        == card_plan.receipt_id
    )
    assert retention_plan.status == (
        "blocked_retention_billing_reconciliation_unimplemented"
    )
    assert retention_plan.adapter_key == "retention_billing_reconciliation"
    assert retention_plan.planned_run_retention_manifest_id == (
        closure_plan.planned_run_retention_manifest_id
    )
    assert retention_plan.planned_billing_reconciliation_id == (
        closure_plan.planned_billing_reconciliation_id
    )
    assert retention_plan.planned_model_usage_rollup_id == (
        notification_plan.planned_model_usage_rollup_id
    )
    assert retention_plan.planned_source_lineage_archive_id == (
        notification_plan.planned_source_lineage_archive_id
    )
    assert retention_plan.planned_run_retention_manifest_status_entry_id == (
        f"{preflight.run_id}-run-retention-manifest-status-entry"
    )
    assert retention_plan.planned_billing_reconciliation_status_entry_id == (
        f"{preflight.run_id}-billing-reconciliation-status-entry"
    )
    assert "billing reconciliation receipt writer" in (
        retention_plan.retention_billing_reconciliation_blockers
    )
    assert "model_usage_rollup_reconciliation_entry_id" in (
        retention_plan.required_retention_billing_reconciliation_receipt_fields
    )
    assert "must require delivery notification reconciliation planning" in (
        retention_plan.required_retention_billing_reconciliation_invariants[0]
    )
    assert retention_plan.blocker_reason == (
        "retention_billing_reconciliation_unimplemented"
    )
    assert retention_plan.retention_billing_reconciliation_allowed is False
    assert retention_plan.run_retention_manifest_created is False
    assert retention_plan.billing_reconciliation_created is False
    assert retention_plan.model_usage_rollup_created is False
    assert retention_plan.source_lineage_archive_created is False
    assert retention_plan.delivery_notification_created is False
    assert retention_plan.workspace_delivery_card_created is False
    assert retention_plan.operator_delivery_ledger_entry_created is False
    assert retention_plan.run_closeout_record_created is False
    assert retention_plan.operator_notification_created is False
    assert retention_plan.private_read_url_created is False
    assert retention_plan.graph_mutated is False
    assert retention_plan.provider_calls_made is False
    assert retention_plan.retrieval_performed is False
    assert retention_plan.final_artifact_created is False
    assert "no retention manifest" in retention_plan.adapter_plan_notes[0]


def test_retention_billing_reconciliation_plan_rejects_notification_state() -> None:
    chain = _accepted_midnight_oil_delivery_notification_reconciliation_plan_chain(
        goal="Reject delivery notification state before retention billing reconciliation planning.",
        source_policy=["web"],
        requested_control_scope=[
            "budget_reservation_provider",
            "model_provider_route_executor",
            "retrieval_executor_source_receipts",
            "graph_mutation_writer",
            "final_html_artifact_writer",
            "operator_live_dispatch_enablement",
        ],
    )
    output_plan = chain["worker_output_aggregation_plan"]
    handoff_plan = chain["worker_synthesis_handoff_plan"]
    assembly_plan = chain["synthesis_bundle_assembly_plan"]
    draft_plan = chain["final_synthesis_draft_plan"]
    html_plan = chain["final_html_artifact_assembly_plan"]
    persistence_plan = chain["final_artifact_persistence_plan"]
    graph_commit_plan = chain["final_artifact_graph_commit_plan"]
    publish_plan = chain["final_artifact_publish_plan"]
    completion_plan = chain["final_artifact_completion_finalization_plan"]
    closure_plan = chain["final_run_closure_plan"]
    readiness_plan = chain["operator_notification_delivery_readiness_plan"]
    apply_plan = chain["operator_notification_delivery_apply_plan"]
    result_plan = chain["operator_notification_delivery_result_reconciliation_plan"]
    ledger_plan = chain["operator_delivery_ledger_reconciliation_plan"]
    card_plan = chain["workspace_delivery_card_reconciliation_plan"]
    bad_notification_plan = chain[
        "delivery_notification_reconciliation_plan"
    ].model_copy(update={"delivery_notification_result_entry_created": True})

    with pytest.raises(
        ValidationError,
        match=(
            "delivery_notification_reconciliation_plan_receipt must not "
            "create delivery notification state"
        ),
    ):
        MidnightOilRetentionBillingReconciliationPlanRequest(
            **_retention_billing_reconciliation_request_kwargs(
                chain,
                output_plan,
                handoff_plan,
                assembly_plan,
                draft_plan,
                html_plan,
                persistence_plan,
                graph_commit_plan,
                publish_plan,
                completion_plan,
                closure_plan,
                readiness_plan,
                apply_plan,
                result_plan,
                ledger_plan,
                card_plan,
                bad_notification_plan,
            )
        )


