def test_operator_archive_package_delivery_report_notification_readiness_plan_records_disabled_requirements() -> None:
    chain = _accepted_midnight_oil_operator_archive_package_delivery_report_result_reconciliation_plan_chain(
        goal="Plan operator archive package delivery report notification readiness after report result reconciliation.",
        source_policy=["arxiv", "web"],
        requested_control_scope=[
            "budget_reservation_provider",
            "model_provider_route_executor",
            "retrieval_executor_source_receipts",
            "graph_mutation_writer",
            "final_html_artifact_writer",
            "operator_live_dispatch_enablement",
        ],
    )
    preflight = chain["preflight"]
    result_reconciliation_plan = chain[
        "operator_archive_package_delivery_report_result_reconciliation_plan"
    ]

    readiness = operator_archive_package_delivery_report_notification_readiness_plan_midnight_oil(
        MidnightOilOperatorArchivePackageDeliveryReportNotificationReadinessPlanRequest(
            **_operator_archive_package_delivery_report_notification_readiness_request_kwargs(
                chain,
                chain["worker_output_aggregation_plan"],
                chain["worker_synthesis_handoff_plan"],
                chain["synthesis_bundle_assembly_plan"],
                chain["final_synthesis_draft_plan"],
                chain["final_html_artifact_assembly_plan"],
                chain["final_artifact_persistence_plan"],
                chain["final_artifact_graph_commit_plan"],
                chain["final_artifact_publish_plan"],
                chain["final_artifact_completion_finalization_plan"],
                chain["final_run_closure_plan"],
                chain["operator_notification_delivery_readiness_plan"],
                chain["operator_notification_delivery_apply_plan"],
                chain["operator_notification_delivery_result_reconciliation_plan"],
                chain["operator_delivery_ledger_reconciliation_plan"],
                chain["workspace_delivery_card_reconciliation_plan"],
                chain["delivery_notification_reconciliation_plan"],
                chain["retention_billing_reconciliation_plan"],
                chain["final_closeout_archive_reconciliation_plan"],
                chain["operator_archive_handoff_package_plan"],
                chain["operator_archive_handoff_package_result_reconciliation_plan"],
                chain["operator_archive_handoff_package_delivery_audit_plan"],
                chain[
                    "operator_archive_handoff_package_delivery_audit_result_reconciliation_plan"
                ],
                chain["operator_archive_package_delivery_report_plan"],
                result_reconciliation_plan,
            )
        )
    )

    assert readiness.receipt_id == (
        f"{preflight.run_id}-operator-archive-package-delivery-report-notification-readiness-plan"
    )
    assert (
        readiness.operator_archive_package_delivery_report_result_reconciliation_plan_receipt_id
        == result_reconciliation_plan.receipt_id
    )
    assert readiness.status == (
        "blocked_operator_archive_package_delivery_report_notification_readiness_unimplemented"
    )
    assert (
        readiness.adapter_key
        == "operator_archive_package_delivery_report_notification_readiness"
    )
    assert (
        readiness.planned_operator_archive_package_delivery_report_notification_readiness_receipt_id
        == f"{preflight.run_id}-operator-archive-package-delivery-report-notification-readiness-receipt"
    )
    assert (
        readiness.planned_operator_archive_package_delivery_report_notification_payload_id
        == f"{preflight.run_id}-operator-archive-package-delivery-report-notification-payload"
    )
    assert "operator archive package delivery report notification payload writer" in (
        readiness.operator_archive_package_delivery_report_notification_readiness_blockers
    )
    assert "operator_archive_package_delivery_report_notification_payload_id" in (
        readiness.required_operator_archive_package_delivery_report_notification_readiness_receipt_fields
    )
    assert readiness.required_operator_archive_package_delivery_report_notification_readiness_invariants[
        0
    ].startswith(
        "operator archive package delivery report notification readiness planner must require report result reconciliation planning"
    )
    assert readiness.blocker_reason == (
        "operator_archive_package_delivery_report_notification_readiness_unimplemented"
    )
    assert readiness.operator_archive_package_delivery_report_notification_readiness_allowed is False
    assert readiness.operator_archive_package_delivery_report_notification_payload_created is False
    assert (
        readiness.operator_archive_package_delivery_report_notification_channel_policy_created
        is False
    )
    assert readiness.operator_archive_package_delivery_report_notification_audit_created is False
    assert (
        readiness.operator_archive_package_delivery_report_result_reconciliation_allowed
        is False
    )
    assert readiness.operator_archive_package_delivery_report_result_entry_created is False
    assert readiness.operator_archive_package_delivery_report_entry_created is False
    assert readiness.operator_archive_package_delivery_audit_result_entry_created is False
    assert readiness.operator_notification_created is False
    assert readiness.private_read_url_created is False
    assert readiness.graph_mutated is False
    assert readiness.provider_calls_made is False
    assert readiness.retrieval_performed is False
    assert readiness.final_artifact_created is False


