def test_operator_archive_package_delivery_report_final_operator_acknowledgement_plan_records_disabled_requirements() -> None:
    chain = _accepted_midnight_oil_operator_archive_package_delivery_report_delivery_confirmation_result_reconciliation_plan_chain(
        goal="Plan operator archive package delivery report final operator acknowledgement after delivery confirmation result reconciliation.",
        source_policy=["arxiv", "web"],
        requested_control_scope=[
            "budget_reservation_provider",
            "model_provider_route_executor",
            "retrieval_executor_source_receipts",
            "graph_mutation_writer",
            "final_html_artifact_writer",
            "operator_live_dispatch_enablement",
        ],
    )
    preflight = chain["preflight"]
    result_plan = chain[
        "operator_archive_package_delivery_report_delivery_confirmation_result_reconciliation_plan"
    ]

    acknowledgement = operator_archive_package_delivery_report_final_operator_acknowledgement_plan_midnight_oil(
        MidnightOilOperatorArchivePackageDeliveryReportFinalOperatorAcknowledgementPlanRequest(
            **_operator_archive_package_delivery_report_final_operator_acknowledgement_request_kwargs(
                chain,
                chain["worker_output_aggregation_plan"],
                chain["worker_synthesis_handoff_plan"],
                chain["synthesis_bundle_assembly_plan"],
                chain["final_synthesis_draft_plan"],
                chain["final_html_artifact_assembly_plan"],
                chain["final_artifact_persistence_plan"],
                chain["final_artifact_graph_commit_plan"],
                chain["final_artifact_publish_plan"],
                chain["final_artifact_completion_finalization_plan"],
                chain["final_run_closure_plan"],
                chain["operator_notification_delivery_readiness_plan"],
                chain["operator_notification_delivery_apply_plan"],
                chain["operator_notification_delivery_result_reconciliation_plan"],
                chain["operator_delivery_ledger_reconciliation_plan"],
                chain["workspace_delivery_card_reconciliation_plan"],
                chain["delivery_notification_reconciliation_plan"],
                chain["retention_billing_reconciliation_plan"],
                chain["final_closeout_archive_reconciliation_plan"],
                chain["operator_archive_handoff_package_plan"],
                chain["operator_archive_handoff_package_result_reconciliation_plan"],
                chain["operator_archive_handoff_package_delivery_audit_plan"],
                chain[
                    "operator_archive_handoff_package_delivery_audit_result_reconciliation_plan"
                ],
                chain["operator_archive_package_delivery_report_plan"],
                chain[
                    "operator_archive_package_delivery_report_result_reconciliation_plan"
                ],
                chain[
                    "operator_archive_package_delivery_report_notification_readiness_plan"
                ],
                chain[
                    "operator_archive_package_delivery_report_notification_result_reconciliation_plan"
                ],
                chain["operator_archive_package_delivery_report_delivery_confirmation_plan"],
                result_plan,
            )
        )
    )

    assert acknowledgement.receipt_id == (
        f"{preflight.run_id}-operator-archive-package-delivery-report-final-operator-acknowledgement-plan"
    )
    assert (
        acknowledgement.operator_archive_package_delivery_report_delivery_confirmation_result_reconciliation_plan_receipt_id
        == result_plan.receipt_id
    )
    assert acknowledgement.status == (
        "blocked_operator_archive_package_delivery_report_final_operator_acknowledgement_unimplemented"
    )
    assert (
        acknowledgement.adapter_key
        == "operator_archive_package_delivery_report_final_operator_acknowledgement"
    )
    assert (
        acknowledgement.planned_operator_archive_package_delivery_report_final_operator_acknowledgement_receipt_id
        == f"{preflight.run_id}-operator-archive-package-delivery-report-final-operator-acknowledgement-receipt"
    )
    assert "operator archive package delivery report final operator acknowledgement entry writer" in (
        acknowledgement.operator_archive_package_delivery_report_final_operator_acknowledgement_blockers
    )
    assert "operator_archive_package_delivery_report_final_operator_acknowledgement_status_entry_id" in (
        acknowledgement.required_operator_archive_package_delivery_report_final_operator_acknowledgement_receipt_fields
    )
    assert acknowledgement.required_operator_archive_package_delivery_report_final_operator_acknowledgement_invariants[
        0
    ].startswith(
        "operator archive package delivery report final operator acknowledgement planner must require delivery confirmation result reconciliation"
    )
    assert acknowledgement.blocker_reason == (
        "operator_archive_package_delivery_report_final_operator_acknowledgement_unimplemented"
    )
    assert (
        acknowledgement.operator_archive_package_delivery_report_final_operator_acknowledgement_allowed
        is False
    )
    assert (
        acknowledgement.operator_archive_package_delivery_report_final_operator_acknowledgement_entry_created
        is False
    )
    assert (
        acknowledgement.operator_archive_package_delivery_report_delivery_confirmation_result_entry_created
        is False
    )
    assert acknowledgement.operator_notification_created is False
    assert acknowledgement.private_read_url_created is False
    assert acknowledgement.graph_mutated is False
    assert acknowledgement.provider_calls_made is False
    assert acknowledgement.retrieval_performed is False
    assert acknowledgement.final_artifact_created is False


